"""What an auto-generated file revision search can filter and order by, and how a row becomes data."""

from __future__ import annotations

from typing import override

from ai.backend.manager.data.auto_generated_file.types import AutoGeneratedFileRevisionData
from ai.backend.manager.models.auto_generated_file_revision.row import AutoGeneratedFileRevisionRow
from ai.backend.manager.models.specs.conditions.datetime import DateTimeConditions
from ai.backend.manager.models.specs.conditions.integer import IntConditions
from ai.backend.manager.models.specs.conditions.uuid import UUIDConditions
from ai.backend.manager.models.specs.orders.column import ColumnOrder
from ai.backend.manager.models.specs.search.converter import RowDataConverter
from ai.backend.manager.models.specs.search.field import SearchableField


class _AutoGeneratedFileRevisionOwnFields(
    RowDataConverter[AutoGeneratedFileRevisionRow, AutoGeneratedFileRevisionData]
):
    """The revision's own columns; the file body cannot be filtered or ordered."""

    field_id = SearchableField(
        AutoGeneratedFileRevisionRow.id,
        UUIDConditions(AutoGeneratedFileRevisionRow.id),
        ColumnOrder(AutoGeneratedFileRevisionRow.id),
    )
    file_id = SearchableField(
        AutoGeneratedFileRevisionRow.file_id,
        UUIDConditions(AutoGeneratedFileRevisionRow.file_id),
        ColumnOrder(AutoGeneratedFileRevisionRow.file_id),
    )
    revision_number = SearchableField(
        AutoGeneratedFileRevisionRow.revision_number,
        IntConditions(AutoGeneratedFileRevisionRow.revision_number),
        ColumnOrder(AutoGeneratedFileRevisionRow.revision_number),
    )
    data = SearchableField(AutoGeneratedFileRevisionRow.data, None, None)
    creator_id = SearchableField(
        AutoGeneratedFileRevisionRow.creator_id,
        UUIDConditions(AutoGeneratedFileRevisionRow.creator_id),
        ColumnOrder(AutoGeneratedFileRevisionRow.creator_id),
    )
    created_at = SearchableField(
        AutoGeneratedFileRevisionRow.created_at,
        DateTimeConditions(AutoGeneratedFileRevisionRow.created_at),
        ColumnOrder(AutoGeneratedFileRevisionRow.created_at),
    )

    @override
    def to_data(self, row: AutoGeneratedFileRevisionRow) -> AutoGeneratedFileRevisionData:
        return AutoGeneratedFileRevisionData(
            id=self.field_id.read(row),
            file_id=self.file_id.read(row),
            revision_number=self.revision_number.read(row),
            data=self.data.read(row),
            creator_id=self.creator_id.read(row),
            created_at=self.created_at.read(row),
        )


class AutoGeneratedFileRevisionSearchableFields:
    own = _AutoGeneratedFileRevisionOwnFields()
